    if (max_cpus == 0) {

        max_cpus = smp_cpus;

    }



    if (max_cpus > MAX_CPUMASK_BITS) {

        fprintf(stderr, "Unsupported number of maxcpus\n");

        exit(1);

    }

    if (max_cpus < smp_cpus) {

        fprintf(stderr, "maxcpus must be equal to or greater than smp\n");

