    av_log(ctx, AV_LOG_INFO, "w:%d h:%d fmt:%s -> w:%d h:%d fmt:%s flags:0x%0x\n",

           inlink ->w, inlink ->h, av_pix_fmt_descriptors[ inlink->format].name,

           outlink->w, outlink->h, av_pix_fmt_descriptors[outlink->format].name,

           scale->flags);



    scale->input_is_pal = av_pix_fmt_descriptors[inlink->format].flags & PIX_FMT_PAL;



    if (scale->sws)

        sws_freeContext(scale->sws);

    scale->sws = sws_getContext(inlink ->w, inlink ->h, inlink ->format,

                                outlink->w, outlink->h, outlink->format,

                                scale->flags, NULL, NULL, NULL);

    if (!scale->sws)

        return AVERROR(EINVAL);





    if (inlink->sample_aspect_ratio.num)

        outlink->sample_aspect_ratio = av_mul_q((AVRational){outlink->h*inlink->w,

                                                             outlink->w*inlink->h},

                                                inlink->sample_aspect_ratio);

    else

        outlink->sample_aspect_ratio = inlink->sample_aspect_ratio;



    return 0;



fail:

    av_log(NULL, AV_LOG_ERROR,

           "Error when evaluating the expression '%s'\n", expr);

    return ret;

}

static AVFrame *apply_palette(AVFilterLink *inlink, AVFrame *in)

{

    int x, y, w, h;

    AVFilterContext *ctx = inlink->dst;

    PaletteUseContext *s = ctx->priv;

    AVFilterLink *outlink = inlink->dst->outputs[0];



    AVFrame *out = ff_get_video_buffer(outlink, outlink->w, outlink->h);

    if (!out) {

        av_frame_free(&in);

        return NULL;

    }

    av_frame_copy_props(out, in);



    set_processing_window(s->diff_mode, s->last_in, in,

                          s->last_out, out, &x, &y, &w, &h);

    av_frame_free(&s->last_in);

    av_frame_free(&s->last_out);

    s->last_in  = av_frame_clone(in);

    s->last_out = av_frame_clone(out);

    if (!s->last_in || !s->last_out ||

        av_frame_make_writable(s->last_in) < 0) {

        av_frame_free(&in);

        av_frame_free(&out);

        return NULL;

    }



    ff_dlog(ctx, "%dx%d rect: (%d;%d) -> (%d,%d) [area:%dx%d]\n",

            w, h, x, y, x+w, y+h, in->width, in->height);



    if (s->set_frame(s, out, in, x, y, w, h) < 0) {

        av_frame_free(&out);

        return NULL;

    }

    memcpy(out->data[1], s->palette, AVPALETTE_SIZE);

    if (s->calc_mean_err)

        debug_mean_error(s, in, out, inlink->frame_count_out);

    av_frame_free(&in);

    return out;

}

