    while(src < c->decomp_buf + c->decomp_size) {

        p1 = *src++;

        if(p1 == 0) { //Escape code

            p2 = *src++;

            if(p2 == 0) { //End-of-line

                output = c->pic.data[0] + (--line) * c->pic.linesize[0];

                pos = 0;

                continue;

            } else if(p2 == 1) { //End-of-picture

                return 0;

            } else if(p2 == 2) { //Skip

                p1 = *src++;

                p2 = *src++;

                line -= p2;

                pos += p1;

                output = c->pic.data[0] + line * c->pic.linesize[0] + pos * (c->bpp / 8);

                continue;

            }

            // Copy data

            for(i = 0; i < p2 * (c->bpp / 8); i++) {

                *output++ = *src++;

            }

	    // RLE8 copy is actually padded - and runs are not!

	    if(c->bpp == 8 && (p2 & 1)) {

		src++;

	    }

            pos += p2;

        } else { //Run of pixels

            int pix[3]; //original pixel

            switch(c->bpp){

            case  8: pix[0] = *src++;

                     break;

            case 16: pix[0] = *src++;

                     pix[1] = *src++;

                     break;

            case 24: pix[0] = *src++;

                     pix[1] = *src++;

                     pix[2] = *src++;

                     break;

            }

            for(i = 0; i < p1; i++) {

                switch(c->bpp){

                case  8: *output++ = pix[0];

                         break;

                case 16: *output++ = pix[0];

                         *output++ = pix[1];

                         break;

                case 24: *output++ = pix[0];

                         *output++ = pix[1];

                         *output++ = pix[2];

                         break;

                }

            }

            pos += p1;

        }

    }



    av_log(c->avctx, AV_LOG_ERROR, "Camtasia warning: no End-of-picture code\n");        

    return 1;

}

