    s->slice_count = 0;



    if (avctx->extradata && !avctx->frame_number) {

        int ret = decode_chunks(avctx, picture, got_output, avctx->extradata, avctx->extradata_size);

        if (ret < 0 && (avctx->err_recognition & AV_EF_EXPLODE))

